import * as fs from 'fs'
import * as path from 'path'
import {
  ProcessExecution,
  RelativePattern,
  Task,
  TaskDefinition,
  TaskGroup,
  TaskProvider,
  WorkspaceFolder,
  workspace,
} from 'vscode'
import { getAssemblerPath, getEmulatorArgs, getEmulatorPath } from '../tools'

export const TASK_TYPE = 'beebvsc'
export const TASK_SOURCE = 'beebvsc'
export const PROBLEM_MATCHER = '$beebasm'
const DEFAULT_DISK_EXT = '.ssd'

export interface BeebVSCTaskDefinition extends TaskDefinition {
  action: 'build' | 'run'
  sourceFile?: string
  diskImage?: string
  bootFile?: string
  extraArgs?: string[]
}

// Limit for automatic discovery of source files, to keep large folders fast
const MAX_DISCOVERED_FILES = 50

// BeebAsm SAVE directive, eg. SAVE "Main", start, end
const saveCommandRegex = /(^|:)\s*SAVE\s+(["'])((?:(?!\2).)*)\2/im

/**
 * Returns the source files listed in beebvsc.sourceFile for the folder,
 * as paths relative to the folder.
 */
export function getConfiguredSourceFiles(folder: WorkspaceFolder): string[] {
  const value = workspace
    .getConfiguration('beebvsc', folder.uri)
    .get<string | string[]>('sourceFile')
  const list = Array.isArray(value) ? value : value ? [value] : []
  return list.map((file) =>
    path.isAbsolute(file) ? path.relative(folder.uri.fsPath, file) : file,
  )
}

/**
 * Returns the target disk image named in beebvsc.targetName, if any.
 */
export function getConfiguredTargetName(
  folder: WorkspaceFolder,
): string | undefined {
  const value = workspace
    .getConfiguration('beebvsc', folder.uri)
    .get<string>('targetName')
  return value ? value : undefined
}

/**
 * Returns the custom disk image name for a configured source file, if
 * beebvsc.targetName doesn't match the default name of any configured source file.
 * The custom name applies to the first configured source file.
 */
export function getCustomDiskImageFor(
  folder: WorkspaceFolder,
  sourceFile: string,
): string | undefined {
  const configured = getConfiguredSourceFiles(folder)
  const targetName = getConfiguredTargetName(folder)
  if (!targetName || configured.length === 0) {
    return undefined
  }
  if (configured.some((file) => getDiskImageFor(file) === targetName)) {
    return undefined
  }
  return sourceFile === configured[0] ? targetName : undefined
}

/**
 * Finds likely BeebAsm root source files in the folder.
 * All .6502 files are included; .asm and .s files are only included if they
 * contain a SAVE directive, as these extensions are also used by other assemblers.
 */
export async function discoverSourceFiles(
  folder: WorkspaceFolder,
): Promise<string[]> {
  const uris = await workspace.findFiles(
    new RelativePattern(folder, '**/*.{6502,asm,s}'),
    '**/node_modules/**',
    MAX_DISCOVERED_FILES,
  )
  const result: string[] = []
  for (const uri of uris) {
    const relative = path.relative(folder.uri.fsPath, uri.fsPath)
    if (relative.toLowerCase().endsWith('.6502')) {
      result.push(relative)
    } else if (getSaveNames(uri.fsPath).length > 0) {
      result.push(relative)
    }
  }
  return result.sort()
}

/**
 * Returns the configured source files, or discovered ones if none are configured.
 */
export async function getSourceFiles(
  folder: WorkspaceFolder,
): Promise<string[]> {
  const configured = getConfiguredSourceFiles(folder)
  return configured.length > 0 ? configured : discoverSourceFiles(folder)
}

/**
 * Returns the names of all files saved by SAVE directives in a source file.
 */
export function getSaveNames(fullPath: string): string[] {
  let text: string
  try {
    text = fs.readFileSync(fullPath, 'utf8')
  } catch {
    return []
  }
  const names: string[] = []
  for (const line of text.split('\n')) {
    // ignore anything after a comment marker
    const code = line.replace(/[;\\].*$/, '')
    const match = saveCommandRegex.exec(code)
    if (match !== null) {
      names.push(match[3])
    }
  }
  return names
}

/**
 * The default disk image for a source file: same name with .ssd extension.
 */
export function getDiskImageFor(sourceFile: string): string {
  const parsed = path.parse(sourceFile)
  return path.join(parsed.dir, parsed.name + DEFAULT_DISK_EXT)
}

/**
 * The default boot file: the first SAVE name in the source, or the source file name.
 */
export function getBootFileFor(
  folder: WorkspaceFolder,
  sourceFile: string,
): string {
  const saves = getSaveNames(path.join(folder.uri.fsPath, sourceFile))
  return saves.length > 0 ? saves[0] : path.parse(sourceFile).name
}

/**
 * Creates the build task for a definition, or undefined if it cannot be built.
 */
export function createBuildTask(
  folder: WorkspaceFolder,
  definition: BeebVSCTaskDefinition,
  name?: string,
): Task | undefined {
  const sourceFile = definition.sourceFile
  if (!sourceFile) {
    return undefined
  }
  const diskImage = definition.diskImage ?? getDiskImageFor(sourceFile)
  const bootFile = definition.bootFile ?? getBootFileFor(folder, sourceFile)
  const args = [
    '-v',
    '-i',
    sourceFile,
    '-do',
    diskImage,
    '-boot',
    bootFile,
    ...(definition.extraArgs ?? []),
  ]
  const execution = new ProcessExecution(getAssemblerPath(folder.uri), args, {
    cwd: folder.uri.fsPath,
  })
  const task = new Task(
    definition,
    folder,
    name ?? `Build ${diskImage}`,
    TASK_SOURCE,
    execution,
    [PROBLEM_MATCHER],
  )
  task.group = TaskGroup.Build
  task.detail = `beebasm -i ${sourceFile} -do ${diskImage}`
  return task
}

/**
 * Creates the emulator run task for a definition, or undefined if there is
 * no disk image to run.
 */
export function createRunTask(
  folder: WorkspaceFolder,
  definition: BeebVSCTaskDefinition,
  name?: string,
): Task | undefined {
  const diskImage =
    definition.diskImage ??
    (definition.sourceFile
      ? getDiskImageFor(definition.sourceFile)
      : getConfiguredTargetName(folder))
  if (!diskImage) {
    return undefined
  }
  const execution = new ProcessExecution(
    getEmulatorPath(folder.uri),
    getEmulatorArgs(diskImage, folder.uri),
    { cwd: folder.uri.fsPath },
  )
  const task = new Task(
    definition,
    folder,
    name ?? `Run ${diskImage}`,
    TASK_SOURCE,
    execution,
    [],
  )
  task.group = TaskGroup.Test
  task.detail = `Run ${diskImage} in ${getEmulatorPath(folder.uri)}`
  return task
}

export class BeebVSCTaskProvider implements TaskProvider {
  async provideTasks(): Promise<Task[]> {
    const tasks: Task[] = []
    for (const folder of workspace.workspaceFolders ?? []) {
      const sources = await getSourceFiles(folder)
      for (const sourceFile of sources) {
        // only include diskImage when it isn't the default, so the definitions
        // match those written by createLaunchConfig() for preLaunchTask
        const diskImage = getCustomDiskImageFor(folder, sourceFile)
        const extra = diskImage ? { diskImage } : {}
        const build = createBuildTask(folder, {
          type: TASK_TYPE,
          action: 'build',
          sourceFile,
          ...extra,
        })
        if (build) {
          tasks.push(build)
        }
        const run = createRunTask(folder, {
          type: TASK_TYPE,
          action: 'run',
          sourceFile,
          ...extra,
        })
        if (run) {
          tasks.push(run)
        }
      }
    }
    return tasks
  }

  resolveTask(task: Task): Task | undefined {
    // Called for 'beebvsc' tasks written in tasks.json: fill in the execution.
    // The returned task must keep the original definition object.
    const definition = task.definition as BeebVSCTaskDefinition
    const folder = getFolderForScope(task.scope)
    if (folder === undefined) {
      return undefined
    }
    let resolved: Task | undefined
    if (definition.action === 'build') {
      resolved = createBuildTask(folder, definition, task.name)
    } else if (definition.action === 'run') {
      resolved = createRunTask(folder, definition, task.name)
    }
    if (resolved && task.group) {
      // keep any group (and isDefault) the user set in tasks.json
      resolved.group = task.group
    }
    return resolved
  }
}

// Folder-scoped tasks use their folder; workspace/global tasks use the first folder
function getFolderForScope(scope: Task['scope']): WorkspaceFolder | undefined {
  if (scope !== undefined && typeof scope === 'object') {
    return scope
  }
  return workspace.workspaceFolders?.[0]
}
